class Task:
    def __init__(self, T, C, D):
        self.T = T  # minimum inter-arrival time
        self.C = C  # worst-case execution time
        self.D = D  # relative deadline
        if D > T:
            # This paper focuses on constrained deadlines, though the definition itself doesn't strictly enforce it.
            # For analysis, D_i <= T_i is assumed.
            pass

def is_directly_blocked(job_J, resource_Rk, current_time, ready_queue, resource_locks):
    # Assume ready_queue is sorted by effective_priority (highest first)
    # Assume resource_locks maps resource_id to holding_job_id

    # Condition 1: J is among the m highest effective-priority jobs
    if job_J not in ready_queue[:m]:
        return False

    # Condition 2: R_k is held by a lower base-priority job
    if resource_Rk in resource_locks:
        holding_job = resource_locks[resource_Rk]
        if holding_job.base_priority < job_J.base_priority:
            # Condition 3: J requested R_k and it's not granted
            if job_J.requested_resource == resource_Rk and not job_J.resource_granted:
                return True

    return False

def is_job_ready(job_J, resource_locks, higher_priority_resource_requests):
    # Assume is_directly_blocked is a function that checks Definition 2
    if is_directly_blocked(job_J, ...):
        return False

    # Check if job_J is requesting a resource held by a higher priority job
    # This is a simplification; the actual check would involve looking at job_J's requests
    # and comparing with resource_locks for higher priority jobs.
    if job_J.requested_resource in higher_priority_resource_requests:
        return False

    return True

class Task:
    def __init__(self, T, C, D):
        self.T = T
        self.C = C
        self.D = D
        self.resource_accesses = {}
        # resource_accesses: dict mapping resource_id to AccessInfo

class AccessInfo:
    def __init__(self, max_requests, max_usage_per_request, max_total_usage):
        self.N_i_k = max_requests
        self.C_i_k = max_usage_per_request
        self.C_Ti_k = max_total_usage

# Global data structure to store highest priority for each resource
resource_highest_priority = {}

def initialize_task_resources(tasks):
    for task_i in tasks:
        for resource_k, access_info in task_i.resource_accesses.items():
            if resource_k not in resource_highest_priority:
                resource_highest_priority[resource_k] = task_i.base_priority
            else:
                resource_highest_priority[resource_k] = min(resource_highest_priority[resource_k], task_i.base_priority)

# L_k would be resource_highest_priority[R_k]

def is_task_set_schedulable(task_set, num_processors):
    for task_i in task_set:
        R_i = calculate_worst_case_response_time(task_i, task_set, num_processors)
        if R_i > task_i.D:
            return False
    return True

def calculate_hp_dsr_interference(task_i, task_set, R_i):
    Ihp_dsr_i = 0
    for resource_k in task_i.RS_i:
        for task_z in task_set:
            if task_z.base_priority < task_i.base_priority: # tau_z has higher priority
                if resource_k in task_z.RS_z:
                    # Here, C_z is considered the 'relevant' execution for W_z
                    # This assumes that any execution of a higher-priority task using a shared resource
                    # can potentially interfere. The 'x' in W_z(t,x) is C_z here.
                    workload_z = calculate_W_z(task_z, R_i, task_z.C)
                    Ihp_dsr_i += workload_z
    return Ihp_dsr_i

def calculate_hp_osr_interference(task_i, task_set, R_i, all_resources):
    Ihp_osr_i = 0
    for resource_k in all_resources:
        if resource_k not in task_i.RS_i:
            for task_z in task_set:
                if task_z.base_priority < task_i.base_priority: # tau_z has higher priority
                    if resource_k in task_z.RS_z:
                        # Here, C_z is considered the 'relevant' execution for W_z
                        workload_z = calculate_W_z(task_z, R_i, task_z.C)
                        Ihp_osr_i += workload_z
    return Ihp_osr_i

import math

def calculate_W_z(task_z, t, x):
    # Assuming this function is defined as in Definition 6
    N_z = math.floor((t - x) / task_z.T) + 1
    return x * N_z + min(x, t - x + task_z.D - task_z.T * N_z)

def calculate_direct_blocking(task_i, task_set):
    DB_i = 0
    for resource_k in task_i.RS_i:
        access_info = task_i.resource_accesses[resource_k]
        DB_i += access_info.N_i_k * access_info.C_i_k
    return DB_i

def calculate_hp_dsr_interference(task_i, task_set, R_i):
    Ihp_dsr_i = 0
    for resource_k in task_i.RS_i:
        for task_z in task_set:
            if task_z.base_priority < task_i.base_priority:
                if resource_k in task_z.RS_z:
                    workload_z = calculate_W_z(task_z, R_i, task_z.C)
                    Ihp_dsr_i += workload_z
    return Ihp_dsr_i

def calculate_hp_osr_interference(task_i, task_set, R_i, all_resources):
    Ihp_osr_i = 0
    for resource_k in all_resources:
        if resource_k not in task_i.RS_i:
            for task_z in task_set:
                if task_z.base_priority < task_i.base_priority:
                    if resource_k in task_z.RS_z:
                        workload_z = calculate_W_z(task_z, R_i, task_z.C)
                        Ihp_osr_i += workload_z
    return Ihp_osr_i

def calculate_hp_nsr_interference(task_i, task_set, R_i):
    Ihp_nsr_i = 0
    for task_z in task_set:
        if task_z.base_priority < task_i.base_priority:
            workload_z = calculate_W_z(task_z, R_i, task_z.C)
            Ihp_nsr_i += workload_z
    return Ihp_nsr_i

def calculate_lpi_multiprocessor_interference(task_i, task_set, R_i, num_processors):
    total_lpi_workload = 0
    for task_z in task_set:
        if task_z.base_priority > task_i.base_priority:
            workload_z = calculate_W_z(task_z, R_i, task_z.C)
            total_lpi_workload += workload_z
    return total_lpi_workload / num_processors

def calculate_worst_case_response_time(task_i, task_set, num_processors, all_resources):
    R_i_current = task_i.C
    while True:
        DB_i = calculate_direct_blocking(task_i, task_set)
        Ihp_dsr_i = calculate_hp_dsr_interference(task_i, task_set, R_i_current)
        Ihp_osr_i = calculate_hp_osr_interference(task_i, task_set, R_i_current, all_resources)
        Ihp_nsr_i = calculate_hp_nsr_interference(task_i, task_set, R_i_current)
        W_lpi_m = calculate_lpi_multiprocessor_interference(task_i, task_set, R_i_current, num_processors)

        R_i_next = task_i.C + DB_i + Ihp_dsr_i + Ihp_osr_i + Ihp_nsr_i + W_lpi_m

        if R_i_next == R_i_current:
            return R_i_next
        if R_i_next > task_i.D: # Optimization: if it exceeds deadline, it's unschedulable
            return R_i_next
        R_i_current = R_i_next

def is_task_schedulable(task_i, task_set, num_processors, all_resources):
    R_i = calculate_worst_case_response_time(task_i, task_set, num_processors, all_resources)
    return R_i <= task_i.D
